reference_solution:
def count_ordered_square_sum_triples(n):
    from math import isqrt
    answer = 0
    for first in range(1, n + 1):
        for second in range(1, n + 1):
            root = isqrt(first * first + second * second)
            if root <= n and root * root == first * first + second * second:
                answer += 1
    return answer

